  const liste = [...motifs].sort();
  const verdict = liste.length ? 'refuse' : 'passe';
  // Le repli en carte : seulement si TOUT ce qui bloque tient à l'automatisme (un geste jamais automatique, la mention, le plafond…).
  const auto2 = e.donnees && e.donnees.action && (e.donnees.action.cible === 'pilote' || e.donnees.action.sans_relecture === true);
  const repli = verdict === 'refuse' && auto2 && liste.every((m) => SEULEMENT_AUTO.has(m) || (m === 'prix_sans_source' && notes.includes('prix_non_source_auto') && !liste.includes('tva_ou_franchise'))) && !liste.includes('lecture_en_erreur') ? 'carte' : null;
  const resultat = { verdict: verdict, motifs: liste, cible: verdict === 'passe' ? e.donnees.action.cible : null, repli: repli };
  return { json: { ...j, statut: verdict === 'passe' ? 'ok' : 'refuse', resultat: resultat, effets_prevus: [],
    journal: [{ evenement: 'conformite', agent: 'lib-porte-conformite', objet_ref: null, decision: (verdict === 'passe' ? 'passe (' + resultat.cible + ')' : 'refusé : ' + liste.join(', ') + (repli ? ' ; repli en carte possible' : '')).slice(0, 200), simulation: e.simulation !== false }] } };
});

// Contrat de sortie de lib-porte-conformite@1 : le seul nœud final ; effets_faits reste vide en simulation.
const CONTRAT = 'lib-porte-conformite@1';
// ─── Gabarit « Contrat de sortie » 035-003 : au-dessus, CONTRAT seulement ; en dessous, le corps commun (empreinte tenue par le juge) ───
const STATUTS = ['ok', 'rien_a_faire', 'rejete', 'refuse', 'erreur'];
const liste = (x) => Array.isArray(x) ? x : [];
return $input.all().map((item) => {
  const j = item.json || {};
  const e = j.enveloppe && typeof j.enveloppe === 'object' ? j.enveloppe : {};
  const simulation = e.simulation !== false;
  const rejete = j.conforme === false;
  const statut = rejete ? 'rejete' : STATUTS.includes(j.statut) ? j.statut : 'erreur';
  const journal = liste(j.journal).slice(0, 200);
  if (rejete) journal.push({ evenement: 'contrat_rejete', agent: CONTRAT, objet_ref: null, decision: 'entrée hors contrat : aucun effet', simulation: simulation });
  return { json: {
    'contrat': CONTRAT,
    'statut': statut,
    'cle_idempotence': typeof e.cle_idempotence === 'string' ? e.cle_idempotence.slice(0, 80) : '',
    'simulation': simulation,
    'resultat': rejete || statut === 'erreur' ? null : (j.resultat && typeof j.resultat === 'object' ? j.resultat : null),
    'effets_prevus': rejete ? [] : liste(j.effets_prevus),
    'effets_faits': simulation || rejete ? [] : liste(j.effets_faits),
    'journal': journal,
    'erreurs': liste(j.erreurs).map(String).slice(0, 20),
  } };
});
